contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g1, bytes32 g2, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);
        c.lockInGuess{value: amount}(g1);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.lockInGuess{value: amount}(g2) { reverted = false; }
        catch { reverted = true; }
        uint balAfter = address(c).balance;
        assert(reverted && balAfter == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g) public payable {
        uint balBefore = address(c).balance;
        bool reverted1;
        try c.settle() { reverted1 = false; }
        catch { reverted1 = true; }
        uint balMid = address(c).balance;
        bool reverted2;
        try c.settle() { reverted2 = false; }
        catch { reverted2 = true; }
        assert(reverted1 && reverted2 && balMid == balBefore && address(c).balance == balBefore);
    }
    receive() external payable {}
}
